# tile patterns as bits foreground6
for br in range(3):
 pats=[]
 for bc in range(4):
  p=tuple(tuple(int(grid[br*6+ir][bc*6+ic]==6) for ic in range(1,6)) for ir in range(1,6))
  pats.append(p)
 print('\nrow',br+1)
 for i,p in enumerate(pats): print(i+1,''.join(''.join(map(str,r)) for r in p))
 print('dist',[[sum(x!=y for ra,rb in zip(pats[i],pats[j]) for x,y in zip(ra,rb)) for j in range(4)] for i in range(4)])
